// THESIS: prompt-group contact sheets with a docked recipe inspector; selection is visual rather than row-driven.
function renderBatches(){return `<main class="workspace">${menuHeader('批次缩略图')}<div class="desk batches-desk">${batchNav()}<section class="panel"><div class="panel-head"><h2>当前批次 / 按提示词归组</h2><span class="sub">4 组 · 每组 3 张</span></div><div class="content-tabs"><span>显示：</span><button data-demo="显示全部作品">全部</button><button data-demo="只显示收藏图片">收藏</button><button data-demo="隐藏点踩作品">隐藏点踩</button><small style="margin-left:auto">缩略图预览</small></div><div class="groups-area">${prompts.map((prompt,g)=>`<section class="prompt-group" data-prompt-group="${g}"><div class="group-head"><span>${String(g+1).padStart(2,'0')}　${prompt.split('，')[0]}</span><small>${g===0?'2 完成 / 1 生成':'3 等待'}</small></div><div class="tiles">${mockTasks.filter(t=>t.batch===g).map(t=>`<article class="tile ${t.status==='等待中'?'pending':''} ${t.id===4?'selected':''}" data-inspect="${t.id}" tabindex="0" aria-label="查看任务 ${t.id} 属性"><div class="tile-picture">${t.id<=2?`<img src="../assets/${t.id===1?'flux2':'qwen'}.png" alt="${t.id===1?'FLUX.2 1024 方图':'Qwen 768 方图'}实际测试输出">`:`${uiIcon(t.status==='生成中'?'clock':'image')}<span>${t.status}</span>`}</div><div class="tile-info"><span>#${String(t.id).padStart(2,'0')}</span><span class="state ${t.cls}">${t.status}</span></div><small style="font-size:10px">${t.model}</small></article>`).join('')}</div></section>`).join('')}<p class="group-note">已完成缩略图使用实际模型测试输出；等待占位不表示已生成图片。</p></div>${batchInput()}</section>${inspector('任务 04 · 等待中')}</div>${footer()}</main>`;}
